// clientLib/bTreeControllers.ts
function openRuleGateway(algoId, label, funcName, args) {
  const index = Nav.indices[Nav.currentIndex];
  const choice = index && index.choices ? index.choices[index.chosen] : null;
  const topicName = choice && choice[0] ? choice[0].topic : "binary tree";
  const buttonText = `back to ${topicName}`;
  if (!pseudoViewer) setPseudoViewer();
  if (label && funcName && args && args.length > 0) {
    pseudoViewer.showAlgorithmWithArgs(algoId, label, funcName, args);
  } else {
    pseudoViewer.showAlgorithm(algoId);
  }
  window.scrollTo(0, 0);
  document.documentElement.scrollTop = 0;
  document.body.scrollTop = 0;
  Nav.setLastVisit();
  Nav.addNavLineBackButton(buttonText);
  Nav.fo.removeChildren();
  Nav.fo.elt.scrollTop = 0;
  Nav.fo.append(pseudoViewer);
  Nav.display();
  pseudoViewer.layout();
  if (typeof requestAnimationFrame !== "undefined") {
    requestAnimationFrame(() => pseudoViewer.layout());
  }
}
function createPillButton(parent, x, y, w, h, label, onClick, title) {
  const grp = new SVGGrpElt();
  grp.setAA([
    "transform",
    `translate(${x}, ${y})`,
    "cursor",
    "pointer",
    "data-ctrl",
    "true",
    "class",
    "diagram-control"
  ]);
  if (title) {
    const titleEl = new SVGElt("title");
    titleEl.setV(title);
    grp.append(titleEl);
  }
  const rect = new SVGElt("rect");
  rect.setAA([
    "x",
    0,
    "y",
    0,
    "width",
    w,
    "height",
    h,
    "rx",
    h / 2,
    "fill",
    "#ffffff",
    "stroke",
    "#cbd5e1",
    "stroke-width",
    1.2,
    "data-ctrl",
    "true"
  ]);
  grp.append(rect);
  const txt = new SVGElt("text");
  txt.setAA([
    "x",
    w / 2,
    "y",
    h / 2 + 0.5,
    "text-anchor",
    "middle",
    "dominant-baseline",
    "central",
    "font-size",
    11,
    "font-weight",
    "600",
    "font-family",
    "system-ui, -apple-system, sans-serif",
    "fill",
    "#475569",
    "pointer-events",
    "none",
    "data-ctrl",
    "true"
  ]);
  txt.setV(label);
  grp.append(txt);
  let isActive = false;
  let currentActiveColor = "#1e40af";
  const updateColors = (isHover) => {
    if (isActive) {
      rect.setAA([
        "fill",
        currentActiveColor,
        "stroke",
        currentActiveColor
      ]);
      txt.setAA(["fill", "#ffffff", "font-weight", "700"]);
    } else if (isHover) {
      rect.setAA([
        "fill",
        "#e2e8f0",
        "stroke",
        "#94a3b8"
      ]);
      txt.setAA(["fill", "#0f172a", "font-weight", "600"]);
    } else {
      rect.setAA([
        "fill",
        "#ffffff",
        "stroke",
        "#cbd5e1"
      ]);
      txt.setAA(["fill", "#475569", "font-weight", "600"]);
    }
  };
  grp.elt.addEventListener("click", (e) => {
    e.stopPropagation();
    onClick();
  });
  grp.elt.addEventListener("mouseenter", () => updateColors(true));
  grp.elt.addEventListener("mouseleave", () => updateColors(false));
  parent.append(grp);
  return {
    group: grp,
    rect,
    text: txt,
    setLabel: (newLabel) => {
      txt.setV(newLabel);
    },
    setActive: (active, activeColor = "#1e40af") => {
      isActive = active;
      currentActiveColor = activeColor;
      updateColors(false);
    }
  };
}
