    headerRow.append(targetLabel);
    const domainBadge = new Elt("span");
    domainBadge.setA("style", "font-size: 11px; font-weight: 600; padding: 2px 8px; background: #e0f2fe; color: #0284c7; border-radius: 4px; font-family: monospace;");
