    this.numberConstants = ["0", "1", "5", "10"];
    this.setVars = ["y\u2081", "y\u2082", "\u2205", "GT5", "LT10"];
    this.availableVars = ["x\u2081", "x\u2082", "y\u2081", "y\u2082", "0", "1", "5", "10", "\u2205", "GT5", "LT10"];
    this.selectedVar = "x\u2081";
    this.slots = [];
